"""Hand-authored preparation for the 30 existing Better Call Saul companion lessons."""
import json
from pathlib import Path
from author_course_guides_c1_c2 import lesson, LESSONS, SOURCES

LESSONS.clear()
ROOT = Path(__file__).resolve().parents[1]

def c(episode, stage, prereqs, purpose, blocks, examples, tasks, bridge, refs):
    lesson(f'cinema-bcs-s01e{episode:02d}-{stage}',prereqs,purpose,blocks,examples,tasks,bridge,refs)

c(1,'prepare','path-present-simple path-present-continuous path-polite-questions',
 'Перед Uno тренируем две вещи: коротко представить себя и попросить немного времени. Задача — понятная просьба, а не убедительная речь с первого предложения.',
 [('Обычная работа и нынешняя задача','I work with local shops — моя обычная работа. I am helping one shop this week — временная задача. Выбирай форму по смыслу, а не только по наличию слова now.'),('Просьба о небольшой возможности','Could you give me five minutes? просит понятную небольшую уступку. Затем скажи, зачем: to explain the plan. Собеседник видит и размер просьбы, и её цель.'),('С чем входить в сцену','Подготовь вопрос: What does he want from the listener? — чего он хочет от собеседника? В эпизоде ищи ответ, а не все неизвестные слова. Учебные фразы здесь авторские, не реплики сериала.')],
 [('I work with small stores.','Я работаю с небольшими магазинами.','Устойчивое занятие.'),('Could you give me five minutes to explain?','Не могли бы вы дать мне пять минут на объяснение?','Ограниченная просьба с понятной целью.')],
 [('Переведи: «Обычно я работаю один, но сегодня помогаю команде». Usually; alone; help a team.','I usually work alone, but today I am helping a team.','Обычное и временное требуют разных форм.','Simple задаёт фон; continuous — сегодняшнюю задачу.'),('Переведи: «Не могли бы вы дать мне минуту?»','Could you give me a minute?','Give me a minute — дать минуту.','Короткая форма уже выполняет реальную просьбу.')],
 'Затем выполни подготовительные переводы. Не переходи к длинному письму, пока можешь уверенно назвать свою роль и размер просьбы.', 'cam-aspect cam-politeness film-method')

c(1,'listen','cinema-bcs-s01e01-prepare path-reading-inference',
 'Во время Uno ищем, как человек пытается заслужить доверие: что он обещает и что собеседник считает риском.',
 [('Первый проход — просьба и реакция','В короткой сцене поймай три вещи: кто просит, о чём и получает ли согласие. Не останавливайся на каждом слове. Если общий смысл потерян, включи английские субтитры и повтори короткий участок.'),('Второй проход — предел обещания','I can explain the options слабее, чем I guarantee success. Услышь can, cannot, only и условия. Именно они показывают, что человек действительно берётся сделать.'),('Проверь, откуда твои сведения','В уроке есть отдельная учебная история о консультанте, а задание по эпизоду требует твоего просмотра. Не смешивай персонажей и факты двух источников. У сцены сохрани свою отметку времени.')],
 [('I can explain the options, but I cannot promise a result.','Я могу объяснить варианты, но не могу обещать результат.','Граница обещания названа прямо.'),('The listener agrees to a short conversation, not to a contract.','Собеседник согласился на короткий разговор, а не на договор.','Маленькое согласие не расширено до большого.')],
 [('Мини-реплика: I can listen for five minutes, but I cannot hire anyone today. На что собеседник согласен? Одно предложение.','The listener agrees to listen for five minutes.','Hire — нанять; это действие пока исключено.','Различаем внимание и решение о найме.'),('Переведи: «Он предлагает объяснение, а не гарантию». Offers an explanation; a guarantee.','He offers an explanation, not a guarantee.','Назови конкретный тип обещания.','Не усиливаем сказанное до гарантированного успеха.')],
 'Сначала ответь по учебному аудиотексту, затем отдельно выбери сцену Uno. При втором просмотре сравни услышанное с субтитрами, потом снова скрой их.', 'film-method captions-study')

c(1,'respond','cinema-bcs-s01e01-listen path-email-basic',
 'Теперь переносим язык знакомства в своё письмо: коротко объяснить пользу, признать сомнение клиента и предложить небольшой следующий шаг.',
 [('Письмо начинается с задачи клиента','Не перечисляй все свои качества. Назови проблему адресата: You need a clear estimate. Затем напиши, что можешь сделать для этой конкретной проблемы.'),('Сомнение можно признать без капитуляции','I understand your concern about my experience не означает «я бесполезен». Это признание понятного вопроса. Дальше предложи проверяемый небольшой шаг, а не чрезмерное обещание.'),('Собери абзац из коротких функций','Проблема → помощь → граница → следующий шаг. Сначала напиши по одному предложению на пункт; затем добавь детали для большого задания. Устную версию сделай короче письменной.')],
 [('I understand your concern about my experience.','Я понимаю ваше сомнение насчёт моего опыта.','Признаём вопрос без самообесценивания.'),('We could start with a short meeting and a written estimate.','Мы могли бы начать с короткой встречи и письменной оценки.','Следующий шаг небольшой и проверяемый.')],
 [('Переведи: «Я могу проверить план, но не могу гарантировать результат». Review the plan; guarantee the result.','I can review the plan, but I cannot guarantee the result.','Назови пользу и предел одним связным сообщением.','Обещание остаётся честным.'),('Предложи следующий шаг: «Начнём с короткого звонка?» Start with a short call.','Could we start with a short call?','Просьба не требует сразу большого обязательства.','Письмо заканчивается действием, на которое можно ответить.')],
 'Из этих четырёх функций собери основной текст. После проверки произнеси его смысл за полминуты без чтения, затем перенеси одну фразу в собственную ситуацию.', 'cam-politeness purdue-concision')

c(2,'prepare','path-zero-first path-second-conditional path-obligation',
 'Перед Mijo учимся предлагать условие и уступку: что мы сделаем, если другой человек сделает свою часть.',
 [('Реальное предложение','If you wait, we will check it — мы считаем ожидание возможным и предлагаем действие. В обычной if-части будущее выражено present: if you wait, не if you will wait только ради будущего.'),('Более отдалённый вариант','If you waited, we could check it tomorrow рассматривает вариант осторожнее. Past-форма тут не обязательно про вчера. Сначала реши, предлагаешь реальный шаг сейчас или обсуждаешь воображаемый вариант.'),('Уступка имеет границу','We can lower the price if… не равно «снизим цену при любых условиях». Укажи свою границу и спроси, подходит ли она. При напряжении прямое Calm down иногда звучит раздражающе; I understand this is frustrating обычно яснее признаёт чувство.')],
 [('If you give us a day, we will fix it.','Если вы дадите нам день, мы это исправим.','Реальная условная договорённость.'),('We could lower the price if the date changed.','Мы могли бы снизить цену, если бы дата изменилась.','Обсуждаем вариант с уступкой, а не обещаем скидку безусловно.')],
 [('Переведи: «Если вы подождёте, мы проверим файл». Wait; check the file.','If you wait, we will check the file.','После if используй wait.','Обе стороны условия названы.'),('Переведи: «Мы можем перенести встречу, но не отменить её». Move the meeting; cancel it.','We can move the meeting, but we cannot cancel it.','Уступка и предел в одной фразе.','Собеседник видит, какие варианты доступны.')],
 'В пяти основных переводах сначала подпиши условие и результат. После этого наблюдай в эпизоде, какое именно требование меняется в переговорах.', 'bc-conditionals cam-politeness')

c(2,'listen','cinema-bcs-s01e02-prepare path-connected-speech',
 'В Mijo тренируем слух на изменении условий: первоначальное требование, уступка и то, что всё ещё неприемлемо.',
 [('Запиши версии до и после','Первое предложение может быть заменено следующим. Не оставляй в итогах оба как одновременно действующие. Запиши исходный вариант, затем стрелкой новый.'),('Услышь маленькое only','Only if, unless, as long as могут полностью менять сделку. Если не услышал условие, переслушай одну реплику с текстом, затем без текста. Не угадывай цену или срок из общего настроения сцены.'),('Пауза — ещё не согласие','I need to think about it сообщает необходимость подумать. Это не yes. В учебном тексте о мероприятии и сцене сериала отдельно проверь, было ли принято решение или разговор лишь продолжился.')],
 [('The discount applies only if we change the date.','Скидка действует только если мы меняем дату.','Условие ограничивает уступку.'),('They have offered a compromise, but it has not been accepted.','Они предложили компромисс, но его ещё не приняли.','Предложение и принятие разделены.')],
 [('Мини-реплика: Friday is possible if you use the smaller room. Назови условие пятницы.','Friday is possible only if they use the smaller room.','Smaller room — меньший зал.','Не выкидываем ограничение варианта.'),('Переведи: «Она попросила время подумать; она ещё не согласилась». Time to think; agreed yet.','She asked for time to think; she has not agreed yet.','Не считай паузу положительным ответом.','Статус решения сохраняется.')],
 'В аудиотексте и сцене веди короткую запись «требование → уступка → граница → статус». Это полезнее попытки переписать весь разговор.', 'film-method cam-discourse')

c(2,'respond','cinema-bcs-s01e02-listen path-email-basic path-connectors-basic',
 'После Mijo нужно написать ограниченный компромисс: уступить в одном вопросе, не обещая уступки во всех будущих случаях.',
 [('Сначала два реальных варианта','Для каждого варианта назови время, место и важный предел. Сравни один и тот же критерий у обоих. Адресат не должен сам искать, почему один дешевле, а другой удобнее.'),('Исключение не отменяет правило','We can make an exception this time ограничивает уступку текущим случаем. Добавь, что останется обязательным. Но не называй exception решение, если контекст уже предусматривает его как нормальный вариант.'),('Предложение заканчивается подтверждением','Please confirm which option works for you просит конкретный ответ. Если нужен срок ответа, назови его. В устной версии сначала скажи рекомендованный вариант, затем причину и условие.')],
 [('We can make an exception this time, but the new deadline must be met.','В этот раз можно сделать исключение, но новый срок нужно соблюсти.','Уступка не стирает новое обязательство.'),('Please confirm which option works for you.','Пожалуйста, подтвердите, какой вариант вам подходит.','Адресату ясно, что ответить.')],
 [('Переведи: «Мы можем перенести срок в этот раз». Extend the deadline; this time.','We can extend the deadline this time.','This time ограничивает уступку случаем.','Не обещаем перенос всех будущих сроков.'),('Допиши условие: We can offer a discount — если вы выберете меньший зал. Choose the smaller room.','We can offer a discount if you choose the smaller room.','Условие рядом с выгодой.','Письмо не скрывает цену компромисса.')],
 'Сначала напиши короткое предложение сделки из двух фраз. Затем расширь его до письма с сравнением двух вариантов и ответом на возражение.', 'cam-politeness purdue-concision')

c(3,'prepare','path-modal-perfect path-polite-questions path-critical-reading',
 'Перед Nacho учимся говорить о подозрении, не превращая его в установленный факт.',
 [('Догадка о прошлом','He might have left — возможно, он ушёл. После might have нужна третья форма left. Must have left выражает сильный вывод, а had to leave — необходимость уйти. Это разные смыслы.'),('Вопрос без скрытого обвинения','Do you know why the times differ? просит объяснить расхождение. Why did you change the time? уже предполагает, что человек изменил время. Сначала проверь, установлен ли такой факт.'),('Назови наблюдение отдельно','The door was open — наблюдение. Someone must have entered — вывод. Для честной версии используй might и укажи, чего ещё не знаешь. Сюжетная догадка зрителя не становится доказательством.')],
 [('He might have left before six.','Возможно, он ушёл до шести.','Возможность, не установленное событие.'),('Do you know why the times are different?','Вы знаете, почему время различается?','Встроенная часть имеет обычный порядок слов.')],
 [('Переведи: «Возможно, она забыла файл». Forget; forgotten.','She might have forgotten the file.','Might have + forgotten.','Говорящий допускает версию.'),('Переведи: «Вы знаете, когда он ушёл?»','Do you know when he left?','Не добавляй did после when.','Внутри вопроса обычный порядок he left.')],
 'Перед просмотром научись писать три строки: увидел, предполагаю, не знаю. Эта разница понадобится в отчёте, а не только в детективной сцене.', 'gmu-hedges bc-reporting')

c(3,'listen','cinema-bcs-s01e03-prepare path-reading-inference',
 'В Nacho важен переход от замеченной детали к версии о произошедшем. Учимся ловить, где именно говорящий делает этот шаг.',
 [('Кто видел сам','I saw him leave — человек сообщает наблюдение. Someone told me he left — пересказывает чужие слова. Не смешивай источник сведений и степень уверенности в них.'),('Свидетельство может поддерживать несколько версий','Запись человека у двери не обязательно показывает, что он взял пропавшую вещь. Спросите, какая ещё версия согласуется с наблюдением. Не нужно верить любой альтернативе — нужно отличать её от исключённой.'),('Два источника держи раздельно','Учебное расследование с ноутбуком существует отдельно от эпизода. На вопросы к нему отвечай по тексту. В сцене сериала опирайся на то, что реально увидел, и укажи момент просмотра.')],
 [('The witness saw him near the door, not taking the laptop.','Свидетель видел его у двери, а не забирающим ноутбук.','Граница наблюдения не расширена.'),('That detail supports a possibility, but does not rule out another explanation.','Деталь поддерживает возможность, но не исключает другое объяснение.','Улика не названа единственным выводом.')],
 [('Мини-факт: A person was seen near the office. Напиши, что это не доказывает вход в кабинет.','Being seen near the office does not prove that the person entered it.','Near — рядом, не внутри.','Наблюдение и вывод имеют разный масштаб.'),('Переведи: «У нас есть версия, но нет подтверждения». A possible explanation; confirmation.','We have a possible explanation, but no confirmation.','Possible explanation — возможное объяснение.','Не подменяем версию фактом.')],
 'На втором прослушивании поймай слова источника: saw, heard, was told, might. Затем перескажи без обвинительной добавки от себя.', 'film-method gmu-hedges')

c(3,'respond','cinema-bcs-s01e03-listen path-argument-essay',
 'После Nacho пишем отчёт, который помогает проверить событие, а не заранее назначить виновного.',
 [('Разложи сообщение на три части','Confirmed facts — проверенное. Possible explanations — версии. Next checks — что проверить. Один и тот же факт не надо повторять как доказанную причину в следующем разделе.'),('Проверка должна различать версии','Если спор касается времени, полезно сверить журнал и часы. Если данных нет, напиши, каких именно не хватает. «Нужно разобраться» слишком расплывчато для следующего действия.'),('Отказ отвечать не доказывает версию','Не придумывай мотив молчания. Можно сообщить, что ответ не получен, и что это оставляет вопрос открытым. Это языковая задача о точном отчёте, не юридическая консультация.')],
 [('The time is confirmed; the reason for the visit is not.','Время подтверждено; причина визита — нет.','Две степени установленности указаны отдельно.'),('We should compare the two records before reaching a conclusion.','Нам следует сравнить две записи перед выводом.','Следующее действие связано с пробелом в данных.')],
 [('Переведи: «Причина неизвестна; нам нужно проверить записи». The reason; check the records.','The reason is unknown; we need to check the records.','Unknown лучше выдуманного объяснения.','После пробела идёт выполнимый шаг.'),('Сделай вывод точнее: He did not answer, so he is guilty.','He did not answer, but that does not prove he is guilty.','Не добавляй новую причину молчания.','Отсутствие ответа не превращается в доказательство обвинения.')],
 'Сначала собери три коротких абзаца без требуемого большого объёма. Затем добавь факты из учебного кейса и проверь, что каждая версия подписана как версия.', 'gmu-hedges purdue-concision')

c(4,'prepare','path-passive-basic path-reported-speech path-critical-reading',
 'Перед Hero учимся описывать публичное событие и отделять заявление компании от того, что подтверждено.',
 [('Событие можно поставить первым','The ad was removed — рекламу убрали. Пассив полезен, если в центре само удаление. Если важно, кто принял решение, добавь by the company или используй активную фразу.'),('Claims — это чей-то голос','The company claims that… показывает владельца утверждения. Не убирай эту рамку, если не проверил содержание. Заявление и факт публикации заявления — разные вещи.'),('Реклама меняет впечатление','Misleading — вводящий в заблуждение. Такое описание нужно обосновать: какие слова или кадры создают лишнее обещание? Не называй любое эффектное изображение ложью без конкретного несоответствия.')],
 [('The ad was removed after complaints.','Рекламу убрали после жалоб.','Событие впереди, исполнитель пока не назван.'),('The company says the claim was taken out of context.','Компания говорит, что заявление вырвали из контекста.','Позиция компании не выдана за проверенный факт.')],
 [('Переведи: «Объявление изменили вчера». The notice; changed.','The notice was changed yesterday.','Was + третья форма changed.','В центре событие изменения.'),('Переведи: «Компания утверждает, что услуга бесплатна». Claims; the service is free.','The company claims that the service is free.','Оставь рамку владельца заявления.','Мы сообщаем заявление, а не независимо подтверждаем бесплатность.')],
 'В просмотре ищи разницу между публичной картинкой и доступными зрителю фактами. В собственных ответах называй конкретную разницу, а не общий ярлык.', 'bc-reporting gmu-hedges')

c(4,'listen','cinema-bcs-s01e04-prepare path-critical-reading',
 'В Hero проверяем, что реклама действительно показывает и какое более широкое впечатление из этого может возникнуть.',
 [('Увиденный случай не равен типичному','One delivery was fast говорит об одном случае. Deliveries are always fast — обобщение. Переслушай слова количества и частоты: one, usually, every, always.'),('Кто о чём спорит','Компания может подтвердить факт съёмки, но не подтверждать типичность услуги. Жители могут просить правила, а не просто отвергать рекламу. Запиши точный предмет каждой позиции.'),('У зрителя иногда больше сведений','В сцене сериала различай знание персонажа и знание аудитории. Объясни, какая дополнительная деталь меняет впечатление, не выдумывая мыслей героя и не используя последующие сезоны.')],
 [('The video shows one successful case, not the usual result.','Видео показывает один успешный случай, а не обычный результат.','Масштаб доказательства ограничен.'),('The residents are asking for clear terms, not denying that the video exists.','Жители просят ясные условия, а не отрицают существование видео.','Возражение описано по его настоящему предмету.')],
 [('Мини-факт: One customer received a free service. Исправь All customers receive it for free.','One customer received the service for free; this does not show that all customers do.','One и all дают разный охват.','Не расширяем единичный случай.'),('Переведи: «Зрителю известна деталь, которой не знает клиент». The viewer; a detail; the client.','The viewer knows a detail that the client does not.','После does not понятно пропущенное know.','Разделяем знания участников.')],
 'Ответ по учебной рекламе сверь с её точными ограничениями. Ответ по Hero отдельно привяжи к выбранной сцене и тому, что в ней доступно зрителю.', 'film-method uvu-rhetoric')

c(4,'respond','cinema-bcs-s01e04-listen path-argument-essay',
 'После Hero пишем критический разбор, в котором ясно, что подтверждено, какой вывод спорен и что помогло бы проверить рекламу.',
 [('Начни с проверяемого','Вместо «компания ужасна» напиши, какое обещание создаёт реклама и какие условия не показаны. Читателю нужен предмет проверки, а не только твоя реакция.'),('Признай реальную пользу','Привлечение внимания может помогать полезному делу. Это не отменяет вопроса о точности сообщения. Хороший ответ может удерживать обе мысли без крайних ярлыков.'),('Предложи ясное исправление','Добавить условия, назвать типичный диапазон или отделить демонстрацию от гарантии — конкретные действия. Выбирай исправление под найденное недопонимание.')],
 [('The campaign draws attention to the service, but leaves its limits unclear.','Кампания привлекает внимание к услуге, но оставляет её ограничения неясными.','Польза и недостаток оценены отдельно.'),('The company should state when the offer applies.','Компании следует указать, когда действует предложение.','Рекомендация отвечает конкретному пробелу.')],
 [('Переведи: «Реклама привлекает внимание, но может вводить в заблуждение». Draws attention; may mislead.','The ad draws attention, but it may mislead people.','May не утверждает установленный обман без доказательств.','Разделены эффект и возможная проблема.'),('Предложи исправление: «Укажите условия рядом с обещанием». State the conditions; next to the promise.','State the conditions next to the promise.','Ограничение должно быть заметно там же.','Читателю легче правильно понять обещание.')],
 'Собери разбор вокруг одного спорного обещания, подкрепи его деталями учебного текста и предложи правку. Затем произнеси ту же мысль без газетного тона.', 'uvu-rhetoric purdue-concision')

c(5,'prepare','path-polite-questions path-relative-basic path-instructions',
 'Перед Alpine Shepherd Boy учимся спрашивать о потребности и объяснять документ простыми словами, не разговаривая с человеком свысока.',
 [('Встроенный вопрос идёт обычным порядком','Could you tell me what you need? После what идут you need, не do you need. Внешняя рамка уже задаёт вопрос. Для ответа да/нет нужна if: Could you tell me if you have a copy?'),('Поясни предмет через функцию','This is the form that confirms your choice — «это форма, которая подтверждает ваш выбор». Короткая that-часть объясняет, зачем документ нужен. Не начинай с внутреннего служебного названия без расшифровки.'),('Дай возможность действовать самому','I can talk you through it — я могу объяснить по шагам. Это отличается от I will do it for you. Сначала выясни, какую помощь человек хочет и на что согласен.')],
 [('Could you tell me what you need?','Не могли бы вы сказать, что вам нужно?','Внутренний порядок слов прямой.'),('This is the form that confirms your choice.','Это форма, которая подтверждает ваш выбор.','Объяснение через понятную функцию.')],
 [('Переведи: «Не могли бы вы сказать, есть ли у вас копия?»','Could you tell me if you have a copy?','If вводит встроенный вопрос да/нет.','Не нужно do you внутри if-части.'),('Переведи: «Это документ, который объясняет следующий шаг». The document; explains the next step.','This is the document that explains the next step.','That соединяет предмет и его функцию.','Документ описан по пользе для читателя.')],
 'Теперь переходи к подготовительным фразам и просмотру. Следи, какие слова делают помощь понятнее и сохраняют возможность самому принять решение.', 'cam-politeness purdue-concision')

c(5,'listen','cinema-bcs-s01e05-prepare path-reading-inference',
 'В этой части слушаем, чего человек хочет от помощника: готового результата, объяснения шагов или возможности попробовать самому.',
 [('Отказ от одной помощи не равен отказу от всей','I do not want you to fill it in for me может сопровождаться просьбой объяснить. Не пересказывай это как She refuses help. Уточни, какой вид помощи принят.'),('Два признака понятного объяснения','Слова first, then, after that делят процесс. Проверка Would you like to try? даёт человеку действие. Найди в учебном тексте эти функции, даже если используются другие слова.'),('В сцене смотри на реакцию','Понятность нельзя установить только по уверенности помощника. Смотри, может ли собеседник объяснить следующий шаг или задать нужный вопрос. Это наблюдение, не диагноз его способностей.')],
 [('She wants an explanation, not someone to take over.','Ей нужно объяснение, а не чтобы всё сделали вместо неё.','Различаются помощь и замена самостоятельного действия.'),('He explains one step and then lets her try.','Он объясняет один шаг, затем даёт ей попробовать.','Помощь разбита на понятные действия.')],
 [('Мини-реплика: Please show me how, but let me do it. Что человек просит? Одно английское предложение.','The person wants guidance while doing the task independently.','Guidance — объяснение и помощь; independently — самостоятельно.','Просьба о помощи сохраняет самостоятельность.'),('Переведи: «Она отказалась от ввода данных за неё, а не от объяснения». Entering the information for her; an explanation.','She refused to have the information entered for her, not an explanation.','Назови именно отвергнутую помощь.','Отказ не обобщается на всё взаимодействие.')],
 'В учебной истории выпиши принятую и отвергнутую помощь. Затем отдельно найди в эпизоде момент, где объяснение меняет понимание собеседника.', 'film-method cam-politeness')

c(5,'respond','cinema-bcs-s01e05-listen path-instructions path-email-basic',
 'После просмотра напишем инструкцию, которой сможет воспользоваться человек без твоих знаний о системе.',
 [('Начни с того, что нужно подготовить','Перед первым нажатием назови материалы: адрес почты, документ или номер, если они нужны в заданном сценарии. Не добавляй личные данные, которые услуга не просит.'),('Один шаг — одно действие','First, open the form. Then enter your name. Короткие команды легче выполнить, чем абзац из нескольких зависимых действий. После сложного шага покажи, как проверить результат.'),('Ошибка тоже часть инструкции','If you see an error message, check… помогает продолжить. Назови конкретную проверку или канал помощи. В конце попроси человека своими словами назвать следующий шаг, а не только сказать «понятно».')],
 [('First, open the form. Then enter your name.','Сначала откройте форму. Затем введите имя.','Действия даны по одному и в порядке выполнения.'),('If the page does not open, check the link.','Если страница не открывается, проверьте ссылку.','Есть понятный путь при сбое.')],
 [('Переведи два шага: «Сначала проверьте данные. Затем отправьте форму». Check the details; submit the form.','First, check the details. Then submit the form.','Не соединяй проверку и отправку в неясное действие.','Порядок защищает от отправки непроверенного.'),('Переведи вопрос для проверки понимания: «Какой следующий шаг?»','What is the next step?','Просим восстановить действие, а не угадать наш ответ.','Человек показывает понимание процесса.')],
 'Расширь два шага в полную инструкцию из задания. Потом прочитай её как новичок: хватает ли информации без твоих устных подсказок?', 'purdue-concision cam-politeness')

c(6,'prepare','path-past-perfect path-modal-perfect path-narrative',
 'Перед Five-O учимся различать событие прошлого, то, что произошло ещё раньше, и сегодняшнее сожаление о прошлом выборе.',
 [('Выбери опорный момент','When I arrived, she had left: мой приезд — опора, её уход — раньше. Had left не означает просто «очень давно». Оно показывает отношение к другой прошлой точке.'),('Сожаление не меняет факт','I should have called означает «мне следовало позвонить». Это оценка упущенного действия. I had to call — была необходимость; I called — факт звонка. Не смешивай эти три сообщения.'),('Факт и самооценку можно разделить','I stayed silent — я промолчал. I let her down — я её подвёл, оценка последствий. В рассказе сначала дай события, затем своё отношение. Не нужно сразу перескакивать к длинной исповеди.')],
 [('When I arrived, the meeting had ended.','Когда я приехал, встреча уже закончилась.','Завершение встречи произошло раньше приезда.'),('I should have spoken up.','Мне следовало высказаться.','Говорящий оценивает прошлое упущение.')],
 [('Переведи: «Когда я позвонил, она уже ушла». Called; had left.','When I called, she had already left.','Уход раньше звонка → had left.','Два события расположены во времени.'),('Переведи: «Мне следовало помочь». Help.','I should have helped.','Should have + третья форма helped.','Речь о сожалении, не о совершённой помощи.')],
 'Перед просмотром построй временную линию из двух событий и одной оценки. Потом используй тот же порядок в длинном рассказе.', 'bc-conditionals cam-aspect')

c(6,'listen','cinema-bcs-s01e06-prepare path-reading-inference',
 'В Five-O отделяем хронологию рассказа от того, как рассказчик теперь оценивает своё поведение.',
 [('Пересказ начинается с временной линии','Назови три события по порядку, даже если герой рассказывает их иначе. Earlier, by then, already и when помогают понять возврат назад. Повторяй только короткий участок, где связь потерялась.'),('Сожаление не устанавливает всю ответственность','I should have done more говорит о самооценке. Она может быть справедливой или слишком широкой. В учебной истории посмотри, какие ограничения добавляет друг, не превращая его поддержку в доказательство всех мотивов.'),('Содержание сериала и учебный кейс разные','Нора из авторской истории не персонаж выбранной сцены. Ответ на учебный вопрос строится по её фактам; временную линию Майка строишь после просмотра своей сцены.')],
 [('She returned after the decision had been made.','Она вернулась после того, как решение уже приняли.','Решение раньше возвращения.'),('He regrets staying silent, but does not know whether speaking would have changed the result.','Он жалеет, что промолчал, но не знает, изменил бы разговор результат.','Сожаление отделено от недоказанного альтернативного исхода.')],
 [('Мини-сцена: Anna called on Friday. The team had decided on Thursday. Что произошло раньше? Одно полное предложение.','The team made the decision before Anna called.','Before называет порядок без догадки о причине.','События упорядочены, мотивы не добавлены.'),('Переведи: «Она жалеет об этом, но результат другого выбора неизвестен». Regrets it; the outcome of a different choice.','She regrets it, but the outcome of a different choice is unknown.','Сожаление и причинный вывод — не одно и то же.','Не заявляем, что прошлое обязательно сложилось бы иначе.')],
 'После прослушивания отдельно запиши факты и оценки. Во время просмотра сделай то же для трёх событий рассказа, сохранив свою отметку сцены.', 'film-method gmu-hedges')

c(6,'respond','cinema-bcs-s01e06-listen path-third-conditional path-narrative',
 'После Five-O пишем историю о сожалении так, чтобы она показывала событие, возможный другой выбор и то, что человек может сделать теперь.',
 [('Рассказу нужен поворот','Сначала исходная ситуация, затем решение, затем поздняя новая информация. Не начинай с длинного общего рассуждения о жизни: один конкретный эпизод даёт читателю опору.'),('Другое прошлое — воображаемое','If I had called, I might have understood earlier допускает возможное последствие. Would have guaranteed success было бы намного сильнее и нуждалось бы в основаниях. Выбирай уверенность честно.'),('Настоящий шаг отдели от отмены прошлого','Нельзя отменить старое решение, но можно объясниться, предложить помощь или изменить следующую привычку. Скажи, что именно доступно сейчас, не обещая этим исправить всё.')],
 [('I cannot change what happened, but I can explain my decision.','Я не могу изменить произошедшее, но могу объяснить своё решение.','Необратимость и нынешнее действие разделены.'),('If I had asked, I might have understood the problem sooner.','Если бы я спросил, возможно, я бы понял проблему раньше.','Альтернативный результат не объявлен гарантированным.')],
 [('Переведи: «Я не могу изменить прошлое, но могу помочь сейчас». The past; help now.','I cannot change the past, but I can help now.','Две временные плоскости с разными возможностями.','Ответ не обесценивает доступное действие.'),('Переведи осторожный другой исход: «Если бы я позвонил, я мог бы узнать раньше». Called; found out sooner.','If I had called, I might have found out sooner.','Might have передаёт возможный, а не доказанный результат.','Другая история остаётся предположением.')],
 'Собери черновик в порядке «событие → оценка → иной вариант → нынешний шаг». Затем расскажи ту же историю вслух, не зачитывая письменные предложения.', 'gmu-hedges purdue-concision')

c(7,'prepare','path-obligation path-quantifiers-nuance path-connectors-basic',
 'Перед Bingo различаем запрет, отсутствие обязанности и добровольное решение, принятое несмотря на выгоду.',
 [('Не обязан и нельзя — противоположные ограничения','You do not have to accept — не обязательно принимать, выбор остаётся. You must not accept — принимать запрещено. Не переводим оба как одно расплывчатое «не надо».'),('Despite требует предмет или -ing','Despite the high pay, she refused — несмотря на высокую оплату. Although it paid well, she refused — хотя работа хорошо оплачивалась. После although есть целая часть с глаголом; после despite здесь существительное.'),('Выбор имеет несколько цен','Выгода может быть финансовой, цена — потеря доверия или времени. Назови каждую отдельно. Обязанность по договору и чувство долга перед человеком не автоматически совпадают.')],
 [('You do not have to accept the offer.','Ты не обязан принимать предложение.','Разрешён выбор, а не введён запрет.'),('Despite the high pay, she turned it down.','Несмотря на высокую оплату, она отказалась.','После despite — группа существительного.')],
 [('Переведи: «Вы не обязаны соглашаться». Agree.','You do not have to agree.','Не используй must not: это был бы запрет.','Сохраняется свобода отказа.'),('Переведи с although: «Хотя предложение выгодное, я откажусь». The offer is attractive; turn it down.','Although the offer is attractive, I will turn it down.','После although нужна полная часть.','Уступка показывает, какая выгода не перевесила решение.')],
 'Перед просмотром сформулируй два честных варианта выбора. Не приписывай персонажу свои ценности; сначала пойми, какие обязательства видит он.', 'cam-politeness cam-discourse')

c(7,'listen','cinema-bcs-s01e07-prepare path-critical-reading',
 'В Bingo слушаем не только «выгодно или нет», но и то, на чём основано обязательство: договор, обещание или доверие.',
 [('Назови источник долга','The contract requires… ссылается на договор. I promised… — на личное обещание. I feel I owe them… — на собственное чувство долга. Эти основания нельзя незаметно заменять одно другим.'),('Уступка другой стороны меняет выбор','Если компания снимает одно ограничение, часть возражения может исчезнуть. Отметь, что именно изменено и что осталось. Не сохраняй старое возражение, если его условие уже сняли.'),('Различай факт и оценку героя','He chose the better-paid job — факт выбора. He betrayed them — сильная оценка. Для второй нужны основания о договорённостях и ожиданиях, а не только твоя симпатия.')],
 [('The contract does not require it, but she made a personal promise.','Договор этого не требует, но она дала личное обещание.','Разные основания обязательства.'),('The company has removed one condition, not every condition.','Компания сняла одно условие, а не все условия.','Масштаб уступки сохранён.')],
 [('Мини-факт: There is no contract, but I promised to help. Назови основание обязательства.','The obligation comes from a personal promise, not a contract.','Personal promise — личное обещание.','Не превращаем моральное объяснение в юридическое.'),('Переведи: «Больше денег не означает, что решение проще». More money; an easier decision.','More money does not mean an easier decision.','Разные критерии могут тянуть в разные стороны.','Не сводим сложный выбор к одной цифре.')],
 'В учебном кейсе выпиши два вида обязательства и изменённое условие. В эпизоде отдельно опиши цену каждого решения по наблюдаемым фактам.', 'film-method uvu-rhetoric')

c(7,'respond','cinema-bcs-s01e07-listen path-argument-essay',
 'После Bingo даём рекомендацию, которая признаёт финансовую сторону и объясняет остальные обязательства без морализаторского ярлыка.',
 [('Два решения оценивай по одним критериям','Сравни доход, обещание, сроки и доверие для каждого варианта. Иначе рекомендация будет подгонять критерии под заранее выбранный ответ.'),('Признай цену своего совета','I recommend keeping the promise, although this reduces your income честно называет потерю. Нельзя обещать, что «правильный» выбор обязательно окупится, если таких данных нет.'),('Рекомендация не забирает выбор','You could negotiate a later start предлагает путь, а не командует чужой жизнью. В конце назови, какую информацию человеку надо проверить перед решением.')],
 [('Keeping the promise protects trust, but has a financial cost.','Выполнение обещания сохраняет доверие, но имеет финансовую цену.','Польза и потеря признаны вместе.'),('You could ask whether a later start is possible.','Можно спросить, возможен ли более поздний старт.','Предложен проверяемый промежуточный вариант.')],
 [('Переведи: «Этот вариант приносит больше денег, но нарушает обещание». Pays more; breaks a promise.','This option pays more, but it breaks a promise.','Назови обе стороны без скрытой гарантии.','Критерии остаются видимыми.'),('Предложи вопрос: «Можно ли начать позже?» Start later.','Would it be possible to start later?','Сначала проверяем возможность компромисса.','Вежливая форма не предполагает заранее согласие другой стороны.')],
 'Собери рекомендацию из сравнения, выбранного критерия, признанной потери и следующего вопроса. Потом защити её устно и ответь на сильное возражение.', 'cam-politeness purdue-concision')

c(8,'prepare','path-present-perfect path-passive-advanced path-quantifiers-nuance',
 'Перед RICO учимся сообщать накопленный результат проверки и не превращать несколько ошибок в утверждение обо всей системе.',
 [('Что уже проверено к настоящему моменту','We have checked ten bills связывает работу с текущим результатом. Ten bills have been checked выдвигает документы вперёд. Have been checked — have + been + третья форма checked.'),('Название количества должно быть точным','Four of the twenty bills — четыре из двадцати проверенных счетов. Это не автоматически четверть всех счетов компании. Всегда назови группу, внутри которой считал.'),('Мало информации и несколько фактов','Little information подчёркивает нехватку. A few discrepancies сообщает, что несколько расхождений есть. Эти формулировки могут быть верны одновременно.')],
 [('We have checked ten bills so far.','К этому моменту мы проверили десять счетов.','Накопленный результат текущей работы.'),('Three of the ten bills contain an error.','В трёх из десяти счетов есть ошибка.','Доля относится к названной проверенной группе.')],
 [('Переведи в пассиве: «Пять счетов уже проверены». Bills; checked.','Five bills have already been checked.','Have been + checked.','Счета в начале; исполнитель может быть неважен.'),('Переведи: «У нас всё ещё мало информации». Still; little information.','We still have little information.','Information неисчисляемое.','Little выражает нехватку, не просто наличие небольшого запаса.')],
 'В переводах сначала назови проверенную группу, затем результат и ограничение. В эпизоде ищи, как единичная деталь становится поводом для более широкой проверки.', 'gmu-hedges cam-determiners')

c(8,'listen','cinema-bcs-s01e08-prepare path-critical-reading',
 'В RICO важен переход от обнаруженного расхождения к проверке закономерности: что можно заключить сейчас и какие документы ещё нужны.',
 [('Запиши размер проверки рядом с выводом','Если изучили десять счетов, не записывай «ошибки во всей компании». В конспекте держи рядом checked, found и sample. Так исходный масштаб не потеряется.'),('Повторение не сразу объясняет причину','Несколько похожих ошибок могут указывать на общий процесс. Но намеренность, причина и полный охват требуют других сведений. Услышь, какое из этих утверждений говорящий действительно делает.'),('Следующий шаг должен отвечать пробелу','Request itemized bills — запросить счета с отдельными позициями. Compare dates — сравнить даты. Слушай, какое действие группа выбрала, не заменяй его своим более драматичным решением.')],
 [('The sample reveals a discrepancy, but not its cause.','Выборка выявляет расхождение, но не его причину.','Наблюдение и объяснение разделены.'),('They decided to request the original records before making a wider claim.','Они решили запросить исходные записи до более широкого заявления.','Проверка предшествует обобщению.')],
 [('Мини-данные: two errors in eight checked bills. Напиши результат с точной группой.','Two of the eight checked bills contained errors.','Не меняй checked bills на all bills.','Количество ошибки связано с размером проверки.'),('Переведи: «Это может быть закономерность, но нам нужны ещё записи». A pattern; more records.','This may be a pattern, but we need more records.','May сохраняет статус предварительной версии.','Не отказываемся от наблюдения и не переоцениваем его.')],
 'Ответь по учебному тексту, сохранив размер выборки и оба ограничения. После просмотра сцены отдельно объясни, какая деталь изменила масштаб вопроса.', 'film-method gmu-hedges')

c(8,'respond','cinema-bcs-s01e08-listen path-email-basic path-argument-essay',
 'После RICO пишем запрос документов так, чтобы адресат понял расхождение и мог ответить, а текст не превращался в неподтверждённое обвинение.',
 [('Укажи предмет проверки','Какие счета, за какой период и какая строка не совпала? Для учебного задания бери эти сведения из кейса. Если номера не даны, не выдумывай их — опиши документы доступным способом.'),('Запроси конкретную опору','Please provide an itemized explanation… просит расшифровку. Не требуй «доказать, что вы честны»: это не проверяемый документ. Свяжи каждую просьбу с замеченным расхождением.'),('Общественный интерес не заменяет точность','Публикация может привлекать внимание, но сильное обвинение требует основания. Можно прямо сообщить обнаруженную проблему и то, что причина проверяется. Это не означает молчать о проверенных фактах.')],
 [('Please explain the difference between these two charges.','Пожалуйста, объясните разницу между этими двумя начислениями.','Запрос привязан к определённому расхождению.'),('We have found errors in the checked records; we have not established their cause.','В проверенных записях найдены ошибки; их причина не установлена.','Сообщение сохраняет факт и предел.')],
 [('Переведи: «Пожалуйста, пришлите счёт с отдельными позициями». An itemized bill.','Please send an itemized bill.','Itemized — с разбивкой по позициям.','Запрос допускает конкретный ответ.'),('Сузь They deliberately overcharged everyone: установлено только расхождение в проверенных счетах.','We found a discrepancy in the bills we checked.','Убери неустановленные deliberate и everyone.','Сильные слова не заменяют доказательство намеренности и охвата.')],
 'Перед длинным письмом составь список «факт — вопрос — нужный документ». После редактуры проверь, что ни один вопрос не содержит выдуманного обвинения.', 'purdue-concision gmu-hedges')

c(9,'prepare','path-clefts path-reporting-verbs path-discussion-b2',
 'Перед Pimento учимся назвать настоящую причину обиды и обозначить границу, не подменяя разговор оценкой личности.',
 [('Выдели конкретное действие','What upset me was your silence — меня расстроило твоё молчание. Рамка выделяет причину. Она полезна, когда собеседник думает, будто проблема только в результате, а ты говоришь о способе решения.'),('Признание не означает согласие на всё','I understand your concern, but… признаёт опасение. Дальше можно ясно сказать, что из этого не следует право решать за другого. Держи обе мысли, а не своди ответ к «ты всегда неправ».'),('Описывай наблюдаемое','You changed the plan without asking me сообщает действие. You have never respected me обобщает отношения и требует гораздо большего основания. Начни с конкретного случая.')],
 [('What upset me was that you did not ask me.','Меня расстроило то, что ты меня не спросил.','Фокус на способе решения, а не только результате.'),('I understand your concern, but the choice is still mine.','Я понимаю твоё опасение, но выбор всё равно за мной.','Сочетаются признание и граница.')],
 [('Переведи с What upset me: «Меня расстроило твоё решение». Your decision.','What upset me was your decision.','После was назови реальную причину.','Рамка не добавляет обвинений о всей личности.'),('Переведи: «Я понимаю риск, но решение должен принять я». Understand the risk; make the decision.','I understand the risk, but I need to make the decision.','Покажи и понимание, и свою роль.','Признание риска не отдаёт право выбора автоматически.')],
 'В сцене ищи, какую конкретную претензию произносят и какое ожидание за ней может стоять. Подтекст записывай как интерпретацию, а не факт.', 'voa-clefts cam-politeness')

c(9,'listen','cinema-bcs-s01e09-prepare path-reading-inference path-prosody',
 'В Pimento слушаем два слоя: о чём люди спорят буквально и какое значение их слова могут иметь для доверия и самостоятельности.',
 [('Сначала буквальная претензия','Запиши одну короткую формулировку того, что человек прямо сказал. Только после этого спроси, какое ожидание она может показывать. Иначе эмоция сцены легко заменит точное содержание.'),('Сильный тон не доказывает скрытый мотив','Пауза, ударение и уклончивый ответ помогают чтению, но не дают доступа к мыслям героя. Для выводов о мотивах нужны реплика, действие и контекст. Оставь возможную альтернативу.'),('Граница слышна в продолжении','I respect your experience, but… может сочетать признание и отказ передать решение. В учебной истории Елены отследи именно это. Её история не является расшифровкой разговора персонажей сериала.')],
 [('She accepts his experience, but not his right to decide for her.','Она признаёт его опыт, но не его право решать за неё.','Согласие и граница относятся к разным вещам.'),('The pause may suggest hesitation; it does not prove the reason for it.','Пауза может показывать колебание, но не доказывает его причину.','Наблюдение отделено от мотива.')],
 [('Мини-реплика: I value your advice, but please ask before changing my plan. Назови границу.','The speaker wants to be asked before the plan is changed.','Не пересказывай это как отказ от любого совета.','Сохраняется конкретное требование к действию.'),('Переведи: «Это возможно подразумевается, но не сказано прямо». May be implied; stated directly.','This may be implied, but it is not stated directly.','May удерживает статус интерпретации.','Подтекст не превращается в буквальную цитату.')],
 'Дай отдельные ответы по учебному кейсу и эпизоду. Для каждого вывода о подтексте укажи наблюдаемую опору и то, чего она всё ещё не устанавливает.', 'film-method cam-discourse rachel-stress')

c(9,'respond','cinema-bcs-s01e09-listen path-proposal path-register-b2',
 'После Pimento пишем письмо о нарушенной договорённости: назвать случай, признать понятную заботу и предложить новый порядок решений.',
 [('Отдели критику работы от права решать','Можно обсуждать качество проекта и одновременно возражать против решения за спиной автора. Эти вопросы не обязаны иметь один ответ. В письме разведи их по предложениям.'),('Граница должна быть выполнимой','Please discuss major changes with me first конкретно задаёт нужное действие. Respect me more звучит важно, но не объясняет, что делать иначе завтра.'),('Новый порядок лучше общего обещания','Предложи, что обсуждать заранее, кто принимает окончательное решение и что делать при разногласии. Не обещай, что это уберёт все конфликты. Это способ вести следующий разговор яснее.')],
 [('I am willing to discuss the quality of my work, but the decision should be discussed with me.','Я готов обсуждать качество своей работы, но решение нужно обсуждать со мной.','Критика не приравнена к праву решать в одиночку.'),('Please raise your concerns with me before changing the plan.','Пожалуйста, обсуди со мной опасения до изменения плана.','Граница переведена в конкретное действие.')],
 [('Переведи: «Я готов обсудить критику, но не согласен с тем, как было принято решение». Discuss the criticism; how the decision was made.','I am willing to discuss the criticism, but I disagree with how the decision was made.','Содержание критики и процедура — разные вопросы.','Письмо сохраняет пространство для разговора.'),('Сформулируй правило: «Пожалуйста, сначала обсуди изменения со мной». Discuss the changes with me first.','Please discuss the changes with me first.','Одно наблюдаемое действие вместо общей оценки характера.','Адресат понимает, что требуется изменить.')],
 'В основном письме сохрани четыре части: случай, его значение, признание разумного опасения, новый порядок. После проверки скажи ту же границу устно коротко.', 'cam-politeness purdue-concision')

c(10,'prepare','path-mixed-conditionals path-narrative path-synthesis',
 'Перед Marco учимся связывать неслучившийся прошлый выбор с воображаемой нынешней жизнью и отличать первоначальный план от результата.',
 [('Две временные точки в одном условии','If I had accepted the job — другой выбор тогда. I would be living abroad now — другая жизнь сейчас. Не нужно автоматически ставить would have в результате, если речь о настоящем.'),('План и итог могут разойтись','I thought I would stay a week описывает ожидание в прошлом. I ended up staying a month сообщает результат. End up + -ing полезно, когда путь привёл не туда, куда ожидали.'),('Выбор не обязан иметь простую причину','Среда, привычка, деньги и отношения могут действовать вместе. Во время финала отмечай отдельные основания, а не ищи одно волшебное слово, которое объяснит всю жизнь героя.')],
 [('If I had taken the job, I would be living elsewhere now.','Если бы я взял ту работу, сейчас жил бы в другом месте.','Прошлое условие связано с нынешним результатом.'),('I planned to stay a week but ended up staying a month.','Я собирался остаться на неделю, а в итоге остался на месяц.','Отделены план и фактический итог.')],
 [('Переведи: «Если бы я тогда переехал, сейчас жил бы рядом». Had moved then; would be living nearby now.','If I had moved then, I would be living nearby now.','Then и now относятся к разным частям.','Не переводим настоящее последствие в законченное прошлое.'),('Переведи: «Я думал, что уйду рано, но в итоге остался». Leave early; ended up staying.','I thought I would leave early, but I ended up staying.','После ended up нужен -ing.','Изменение результата видно без длинного объяснения.')],
 'Перед финалом потренируй эти две рамки на своём вымышленном примере. Затем наблюдай, какие ожидания героя подтверждаются, а какие меняются.', 'bc-conditionals cam-aspect')

c(10,'listen','cinema-bcs-s01e10-prepare path-longform-reading',
 'В Marco следим за изменением плана и за тем, какие варианты герой сравнивает честно, а какие видит через привычку или воспоминание.',
 [('Запиши план отдельно от результата','Слова intended, expected, thought показывают ожидание. Ended up, eventually сообщают, к чему пришли. Не пересказывай первоначальный план как уже выполненное действие.'),('Проверь основание сравнения','Знакомая среда может казаться надёжнее потому, что её легче представить. Новая возможность может казаться лучше из-за неизвестных недостатков. Это возможные объяснения; привяжи их к сцене, а не диагностируй человека.'),('Внешние события и внутренний вывод раздельны','Герой вернулся — событие. Он вернулся, потому что ценит принадлежность, — интерпретация, если не названа прямо. Не используй дальнейшие сезоны для объяснения того, что на этом этапе ещё не известно.')],
 [('He intended to leave early, but stayed longer than planned.','Он собирался уйти рано, но остался дольше, чем планировал.','Ожидание и результат различаются.'),('Familiarity may influence the choice, but it is not the only possible factor.','Привычность может влиять на выбор, но это не единственный возможный фактор.','Интерпретация не стала единственной причиной.')],
 [('Мини-реплика: I expected a short visit, but I stayed for weeks. Передай, что изменилось.','The visit lasted much longer than expected.','Lasted — длился; than expected — чем ожидалось.','Отслеживаем изменение плана, не выдумываем причину.'),('Переведи: «Нам нужна информация о обоих вариантах, а не только о знакомом». Both options; the familiar one.','We need information about both options, not just the familiar one.','One заменяет option.','Сравнение должно иметь сведения по обеим сторонам.')],
 'Разбери сначала изменение плана в учебной истории, затем два выбранных момента финала. Для интерпретации выбора оставь хотя бы одну альтернативу.', 'film-method gmu-hedges')

c(10,'respond','cinema-bcs-s01e10-listen path-synthesis path-argument-essay',
 'Финал кинокурса — собственный аргумент о выборе человека. Сезон даёт материал, но вывод нужно построить и проверить возражением.',
 [('Тезис должен позволять спор','Среда влияет на выбор слишком широко для сильного анализа. Уточни, когда и через что: знакомые отношения могут перевешивать новую карьерную возможность. Это позиция для проверки, а не универсальный закон.'),('Сцена нужна как опора, не пересказ серии','Коротко назови наблюдаемое решение, затем объясни, как оно поддерживает тезис. Добавь сцену, которая усложняет вывод. Не подменяй анализ пересказом всех десяти эпизодов.'),('Сильное возражение улучшает итог','Сформулируй реальный аргумент противоположной стороны. Потом сузь свой вывод, если нужно: not always, in this situation, one factor. Через день попробуй объяснить ту же мысль на новом жизненном примере.')],
 [('The familiar environment influences his choice, but does not remove his responsibility.','Привычная среда влияет на его выбор, но не снимает ответственности.','Два аспекта могут сосуществовать.'),('This scene supports my argument, while the later choice complicates it.','Эта сцена поддерживает мой аргумент, а поздний выбор его осложняет.','Анализ учитывает неудобное свидетельство.')],
 [('Переведи тезис с ограничением: «Среда влияет на выбор, но не полностью его определяет». Environment; influences; determines.','The environment influences a choice, but does not determine it completely.','Не превращай влияние в единственную причину.','Тезис оставляет место другим основаниям.'),('Начни сильное возражение: «Однако тот же опыт мог бы привести другого человека к иному решению». The same experience; lead another person to a different decision.','However, the same experience could lead another person to a different decision.','Could обозначает правдоподобную альтернативу.','Возражение проверяет слишком широкий вывод.')],
 'Напиши основной анализ, затем отдельное возражение и уточнённый итог. Устная версия должна передавать логику без чтения текста; итог сезона не является автоматическим подтверждением C1.', 'purdue-synthesis uvu-rhetoric')

def build():
    raw=json.loads((ROOT/'content/courses/cinema-lessons.json').read_text(encoding='utf-8'))
    original=raw.get('lessons',[]) if isinstance(raw,dict) else raw
    assert {x['lessonId'] for x in LESSONS}=={x['id'] for x in original}
    assert len(LESSONS)==30
    extra=[
        dict(id='film-method',title='British Council: How can film help you teach or learn English?',url='https://www.britishcouncil.org/voices-magazine/how-can-film-help-you-teach-or-learn-english',kind='teaching-method',notes='Короткая сцена как материал для осмысленных языковых действий; не источник диалогов сериала.'),
        dict(id='captions-study',title='Pujadas & Muñoz: TV viewing comprehension through captions and subtitles',url='https://www.cambridge.org/core/product/identifier/S0272263120000042/type/journal_article',kind='research',notes='Публичное описание исследования: роль уровня, предварительного словаря и субтитров. Не обоснование универсального запрета субтитров и не обещание конкретного роста уровня.')
    ]
    used={s for x in LESSONS for s in x['sourceIds']}
    sources=[dict(id=i,title=t,url=u,kind=k,notes=n) for i,t,u,k,n in SOURCES if i in used]+extra
    assert used=={s['id'] for s in sources}
    target=ROOT/'content/course-guides-cinema.json'
    target.write_text(json.dumps(dict(version=1,sources=sources,lessons=LESSONS),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Wrote 30 cinema guides / 60 preparatory exercises')

if __name__=='__main__':
    build()
